def shade(cell, fill):
    v=OxmlElement('w:shd');v.set(qn('w:fill'),fill);cell._tc.get_or_add_tcPr().append(v)

def table(doc, headers, rows, widths):
    t=doc.add_table(rows=1, cols=len(headers));t.autofit=False
    for c,w in zip(t.columns,widths):c.width=Cm(w)
    for i,h in enumerate(headers):t.rows[0].cells[i].text=h
    repeat=OxmlElement('w:tblHeader');t.rows[0]._tr.get_or_add_trPr().append(repeat)
    for row in rows:
        cells=t.add_row().cells
        for i,v in enumerate(row):cells[i].text=str(v)
    for ri,row in enumerate(t.rows):
        nr=OxmlElement('w:cantSplit');row._tr.get_or_add_trPr().append(nr)
        for ci,cell in enumerate(row.cells):
            cell.width=Cm(widths[ci]);cell.vertical_alignment=1
            pr=cell._tc.get_or_add_tcPr();mar=OxmlElement('w:tcMar')
            for side,n in [('top',90),('bottom',90),('left',110),('right',110)]:
                e=OxmlElement('w:'+side);e.set(qn('w:w'),str(n));e.set(qn('w:type'),'dxa');mar.append(e)
            pr.append(mar);b=OxmlElement('w:tcBorders')
            for side in ['top','left','bottom','right']:
                e=OxmlElement('w:'+side);e.set(qn('w:val'),'single');e.set(qn('w:sz'),'4');e.set(qn('w:color'),'D9D9D9');b.append(e)
            pr.append(b)
            if ri==0:shade(cell,'EDF0F5')
            for p in cell.paragraphs:
                p.paragraph_format.space_after=Pt(1);p.paragraph_format.space_before=Pt(1)
                p.paragraph_format.line_spacing=1.05
                for r in p.runs:r.font.size=Pt(9.5);r.font.bold=ri==0;r.font.color.rgb=RGBColor.from_string('000000')
    doc.add_paragraph().paragraph_format.space_after=Pt(0)
    return t

def p(doc,text,style=None):
    v=doc.add_paragraph(text,style);return v

def clause(doc,n,title,text):
    v=doc.add_paragraph();r=v.add_run(f'{n}  {title}. ');r.bold=True;v.add_run(text);return v

def heading(doc,n,title,lead=None):
    if n>1:doc.add_page_break()
    p(doc,f'{n:02d}   /   УСЛОВИЯ ЗАКАЗА','Kicker')
    doc.add_heading(title,level=1)
    if lead:p(doc,lead,'Lead')

def tag(doc,text):
    doc.add_paragraph(text,'Tag')

