    cp=d.core_properties;cp.title='Спецификация заказа';cp.subject='Индивидуальные условия работы';cp.author='Академический Салон';cp.last_modified_by='';cp.comments='';cp.keywords='';cp.revision=1
    cp.created=datetime(2026,9,9,0,0,tzinfo=timezone.utc);cp.modified=cp.created
    settings=d.settings.element;lang=OxmlElement('w:themeFontLang');lang.set(qn('w:val'),'ru-RU');settings.append(lang)
    return d

